// Mirrors the Python read-only selector. Policy and facts are generated by Nour.
import queries from './query.cjs';
export function retrieve(index, symbols, question) {
  if(!Array.isArray(symbols)||symbols.length<1||symbols.length>2||symbols.some(s=>typeof s!=='string'||(s!=='MASI'&&!Object.hasOwn(index.symbols,s))))throw new Error('Choisissez un ou deux titres présents dans Nour.');
  const q=question.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  let routes=index.policy.routes.filter(r=>new RegExp('\\b(?:'+r.pattern+')').test(q));
  if(!routes.length)routes=index.policy.routes.slice(0,1);
  if(routes.some(r=>r.id==='briefing'))routes=routes.filter(r=>r.id!=='overview');
  if(routes.some(r=>r.id==='overview'))routes=routes.filter(r=>['overview','news','macro','quality'].includes(r.id));
  const base=['symbol','name','sector','url','price','price_source','asof','decision','age_calendar_days','quality','history_readiness','collection_conflicts','day_shares','day_turnover_mad_actual','issuer_status','history_provenance'];
  const fields=new Set([...base,...routes.flatMap(r=>r.fields)]),keys=new Set(routes.flatMap(r=>r.definitions));
  const selected={};
  for(const s of [...new Set(symbols)]){
    const dates=Object.keys(index.masi_history||{}).sort();
    selected[s]=s==='MASI'?{market:index.market,history_first:dates[0]||null,history_last:dates.at(-1)||null,history_sessions:dates.length}:Object.fromEntries(Object.entries(index.symbols[s]).filter(([k])=>fields.has(k)));
  }
  const dates=[...question.matchAll(/\b(20\d{2}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/(?:20\d{2}|\d{2}))\b/g)].map(m=>{
    const parts=m[0].split('/');
    const d=parts.length===3?`${parts[2].length===2?'20'+parts[2]:parts[2]}-${parts[1].padStart(2,'0')}-${parts[0].padStart(2,'0')}`:m[0];
    const parsed=new Date(d+'T00:00:00Z');
    if(!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==d)throw new Error('Date invalide.');
    return d;
  });
  if(dates.length>6)throw new Error('Limitez la question à six dates.');
  const historical=dates.length>0&&(!routes.some(r=>['news','macro','briefing'].includes(r.id))||routes.some(r=>['fundamentals','technical','risk','score','laboratory'].includes(r.id)));
  if(historical)for(const [s,row] of Object.entries(selected)){
    if(s==='MASI')continue;
    selected[s]={...Object.fromEntries(Object.entries(row).filter(([k])=>['symbol','name','url'].includes(k))),requested_dates:dates,historical_measure_status:'not_retrieved_use_verified_local_history'};
  }
  const result={analysis_date:index.analysis_date,snapshot_updated:index.snapshot_updated,snapshot_id:index.snapshot_id,intents:routes.map(r=>r.id),rules:index.policy.rules,selected,
    definitions:Object.fromEntries([...keys].sort().filter(k=>Object.hasOwn(index.definitions,k)).map(k=>[k,index.definitions[k]])),
    masi_dates:Object.fromEntries(dates.map(d=>[d,index.masi_history?.[d]??null])),
    limitations:['Aucune série brute ni ligne de laboratoire transmise. Pour une date de titre non fournie, consulter son historique sourcé ; ne pas inventer.']};
  if(!historical&&result.intents.some(i=>['overview','quality','news'].includes(i)))Object.assign(result,{market:index.market,collection:index.health,provenance:index.provenance});
  if(result.intents.some(i=>['news','overview'].includes(i))){
    result.news=index.news.filter(a=>symbols.includes('MASI')||(a.tickers||[]).some(t=>symbols.includes(t))).sort((a,b)=>(b.published_at||'').localeCompare(a.published_at||'')).slice(0,4);
    result.news_notice='Métadonnées de veille seulement ; aucune cause de variation démontrée et aucun fait comptable certifié par ce flux.';
  }
  if(result.intents.includes('macro'))result.macro=index.macro;
  if(result.intents.includes('briefing')){
    const key=/matin/.test(q)?'briefing-matin':/midi|mi.journee/.test(q)?'briefing-midi':/fin de journee|edition.*cloture/.test(q)?'briefing-cloture':/cloture/.test(q)?'cloture':'briefing';
    let briefing=structuredClone(index.briefings?.[key]||null);
    if(briefing){briefing.focus=(briefing.focus||[]).filter(f=>symbols.includes(f.symbol));if(dates.some(d=>d!==briefing.generated_for&&d!==briefing.market_session))briefing=null;}
    result.briefings=briefing?{[key]:briefing}:{};
    result.briefing_notice='Édition et paragraphes descriptifs déjà publiés par Nour ; pas de nouvelle analyse ni de causalité démontrée. Les données absentes ne sont pas reconstituées.';
  }
  if(!historical){
    if(symbols.length===1&&symbols[0]==='MASI'){
      const query=queries.select(index,question);if(query)result.query_result=query;
    }
    if(result.intents.some(i=>['quality','overview'].includes(i)))for(const key of ['coverage','market_volume_audit','intraday','score_archive'])result[key]=index[key]??null;
  }
  const size=()=>new TextEncoder().encode(JSON.stringify(result)).byteLength;
  const query=result.query_result;
  if(query?.rows.length){const total=query.rows.length;while(size()>index.policy.max_context_bytes&&query.rows.length>1){query.rows.pop();query.omitted_for_context_budget=total-query.rows.length;query.context_notice='Sélection IA limitée aux premiers titres affichés pour conserver leurs preuves et réserves intégrales. Le résultat local conserve la liste demandée.';}}
  if(size()>index.policy.max_context_bytes)throw new Error('Les preuves requises dépassent le budget IA. Posez une question ciblée ; les données locales restent disponibles.');
  return result;
}

export function sources(context){
  const result=[{label:'Marché et sources Nour',url:'index.html'}];
  for(const [symbol,row] of Object.entries(context.selected)){
    if(symbol==='MASI')continue;
    result.push({label:`Fiche ${symbol} · ${row.asof}`,url:row.url});
    for(const source of row.issuer_status?.sources||[]){try{const u=new URL(source.url);if(u.protocol==='https:'&&!u.username&&!u.password)result.push({label:`${symbol} · ${source.label}`,url:u.href});}catch{}}
    const f=row.fundamental||{};
    for(const [key,e] of Object.entries(f.evidence||{})){
      const url=e.document_url||f.document_url;
      try{const u=new URL(url);if(u.protocol==='https:'&&!u.username&&!u.password&&Number.isInteger(e.page)&&e.page>0){u.hash='page='+e.page;result.push({label:`${symbol} · ${key} · page PDF ${e.page}`,url:u.href});}}catch{}
    }
    for(const [label,url] of [['Comptes annuels',f.document_url],['Dernière publication',f.latest_report?.document_url]]){
      try{const u=new URL(url);if(u.protocol==='https:'&&!u.username&&!u.password)result.push({label:`${symbol} · ${label}`,url:u.href});}catch{}
    }
  }
  for(const row of context.query_result?.rows||[]){
    result.push(...sources({selected:{[row.symbol]:{...row,fundamental:{evidence:row.evidence,document_url:row.document_url}}}}).slice(1));
  }
  return result;
}
